/* Editor tools built on the SVG scene graph. No services or accounts are required. */
class StudioCanvas extends PosterCanvas {
 constructor(){
   super();this.selection=new Set();this.zoom=100;this.snap=false;this.grid=false;this.artLimit=48;this.collection='all';this.layerQuery='';this.activeProject=null;
   try{this.favorites=new Set(JSON.parse(localStorage.getItem('paperplane-favorite-art')||'[]'));}catch{this.favorites=new Set();}
   this.installUI();
 }
 dimensions(){return posterDimensions(state);}
 seed(look){if(state.blank&&look===state.look){const h=this.dimensions().height;return{height:h,nodes:[this.makeNode(`<rect width="600" height="${h}" fill="${this.colors()[0]}"/>`,'Background',{role:'background',locked:true})]};}return super.seed(look);}
 installUI(){
   document.querySelector('.or').insertAdjacentHTML('afterend',`<div class="catalog-tools"><label><span class="sr-only">Search poster categories</span><input id="catalogSearch" placeholder="Explore more: sports, hiring, menus, film…"></label><button data-command="catalog-more" id="catalogMore">Explore all ${categories.length} types ↗</button><button data-command="blank">＋ Start blank</button></div><div id="catalogCount" class="catalog-count"></div>`);
   document.querySelector('#catalogSearch').addEventListener('input',()=>this.filterCategories());
   document.querySelector('#categories').innerHTML=categories.map(categoryCard).join('');this.filterCategories();
   const choose=setCategory;setCategory=(id,fromBrief=false)=>{choose(id,fromBrief);let alternatives=document.querySelector('#matchAlternatives');if(!alternatives){alternatives=document.createElement('div');alternatives.id='matchAlternatives';alternatives.className='match-alternatives';document.querySelector('#matchSummary').after(alternatives);}const other=fromBrief?rankBrief(state.brief).filter(r=>r.score>0&&r.c.id!==id).slice(0,3):[];alternatives.innerHTML=other.length?'Also fits: '+other.map(r=>`<button data-category="${r.c.id}">${r.c.name}</button>`).join(''):'';};
   const paper=document.querySelector('#paper');paper.innerHTML=Object.entries(PAPER_FORMATS).map(([id,f])=>`<option value="${id}">${f.label}</option>`).join('');
   paper.closest('label').insertAdjacentHTML('afterend','<div id="customPaper" class="two-col" hidden><label>Width (mm)<input id="customWidth" type="number" min="30" max="1000" value="210"></label><label>Height (mm)<input id="customHeight" type="number" min="30" max="1000" value="297"></label></div>');
   for(const key of ['customWidth','customHeight'])document.querySelector('#'+key).addEventListener('input',e=>{const value=Number(e.target.value);if(value<30||value>1000)return;this.checkpoint(true,key);state[key]=value;this.changed();});
   const host=this.host,viewport=document.createElement('div');viewport.className='canvas-viewport';viewport.id='canvasViewport';host.before(viewport);viewport.append(host);
   document.querySelector('.canvas-toolbar').insertAdjacentHTML('afterend',`<div class="studio-tools"><div><label><input id="snapToggle" type="checkbox"> Snap</label><label><input id="gridToggle" type="checkbox"> Grid</label></div><div><button data-command="select-all" title="Select unlocked visible elements (Ctrl+A)">Select all</button><button data-command="group" title="Group selected elements (Ctrl+G)">Group</button><select id="canvasZoom" aria-label="Canvas zoom">${[50,75,100,125,150,200].map(z=>`<option ${z===100?'selected':''} value="${z}">${z}%</option>`).join('')}</select><button data-command="help" aria-label="Keyboard shortcuts">?</button></div></div>`);
   document.querySelector('#canvasZoom').addEventListener('change',e=>{this.zoom=Number(e.target.value);this.applyZoom();});
   document.querySelector('#snapToggle').addEventListener('change',e=>this.snap=e.target.checked);
   document.querySelector('#gridToggle').addEventListener('change',e=>{this.grid=e.target.checked;this.paint();});
   document.querySelector('#exportType').insertAdjacentHTML('beforeend','<option value="jpeg">JPEG image</option>');
   document.querySelector('.export-controls').insertAdjacentHTML('afterbegin','<button class="studio-button" data-command="projects">Projects</button><button class="studio-button" data-command="print">Print / PDF</button><select id="exportQuality" aria-label="Export resolution"><option value="300">300 DPI print</option><option value="150">150 DPI</option><option value="72">72 DPI screen</option></select>');
   document.querySelector('#drafts').onclick=()=>this.projects();
   document.querySelector('#artSearch').insertAdjacentHTML('afterend',`<div class="library-controls"><select id="artCollection" aria-label="Artwork collection"><option value="all">All graphics</option><option value="food">Food & drinks</option><option value="animals">Animals & nature</option><option value="work">Work & learning</option><option value="outdoor">Sports & outdoors</option><option value="graphic">Shapes & patterns</option><option value="favorites">★ Favorites</option></select><span id="artCount"></span></div>`);
   document.querySelector('#artCollection').addEventListener('change',e=>{this.collection=e.target.value;this.artLimit=48;this.renderLibrary();});
   document.querySelector('#artSearch').addEventListener('input',()=>{this.artLimit=48;this.renderLibrary();},true);
   document.querySelector('#artGrid').insertAdjacentHTML('afterend','<button class="library-more" data-command="more-art" id="moreArt">Show more artwork</button>');
   document.querySelector('#moreArt').insertAdjacentHTML('afterend','<label class="upload">＋ Import your SVG<input id="svgImport" type="file" accept=".svg,image/svg+xml" hidden></label>');
   document.querySelector('#svgImport').addEventListener('change',e=>this.importSvg(e));
   document.body.insertAdjacentHTML('beforeend',`<dialog id="projectDialog" class="studio-dialog"><div class="dialog-heading"><h2>Your projects</h2><button data-command="close-dialog" aria-label="Close projects">×</button></div><p>Keep separate designs in this browser, or download an editable project file to use elsewhere.</p><div class="project-save"><label><span class="sr-only">Project name</span><input id="projectName" maxlength="80" placeholder="Give this poster a name"></label><button data-command="save-project" class="primary">Save project</button></div><div class="project-file-actions"><button data-command="export-project">↓ Download project</button><label>↑ Open project file<input type="file" id="projectImport" accept=".json,.paperplane" hidden></label><button data-command="current-draft">Current draft</button></div><div id="projectList" class="project-list"></div><p class="hint" id="projectMessage"></p></dialog><dialog id="shortcutsDialog" class="studio-dialog"><div class="dialog-heading"><h2>A few handy shortcuts</h2><button data-command="close-help" aria-label="Close shortcuts">×</button></div><dl class="shortcut-list"><dt>Shift + click</dt><dd>Add or remove from selection</dd><dt>Ctrl / Cmd + A</dt><dd>Select all unlocked, visible layers</dd><dt>Ctrl / Cmd + G</dt><dd>Group selection</dd><dt>Ctrl / Cmd + Shift + G</dt><dd>Ungroup</dd><dt>Ctrl / Cmd + D</dt><dd>Duplicate selection</dd><dt>Arrow keys / Shift + arrows</dt><dd>Move by 1 / 10 poster units</dd><dt>Ctrl / Cmd + Z / Shift + Z</dt><dd>Undo / redo</dd><dt>Shift while resizing</dt><dd>Keep proportions</dd><dt>Alt while dragging</dt><dd>Temporarily bypass snapping</dd><dt>Escape</dt><dd>Clear selection</dd></dl></dialog>`);
   document.querySelector('#projectImport').addEventListener('change',e=>this.importProject(e));
   document.querySelector('.project-file-actions').insertAdjacentHTML('beforeend','<button data-command="save-copy">Save a copy</button>');
   this.resizeObserver=new ResizeObserver(()=>this.applyZoom());this.resizeObserver.observe(document.querySelector('#canvasViewport'));
 }
 filterCategories(){const q=document.querySelector('#catalogSearch').value.toLowerCase().trim();let count=0;document.querySelectorAll('#categories [data-category]').forEach((el,i)=>{const c=categories[i];const match=!q||[c.name,c.desc,...c.keywords].join(' ').toLowerCase().includes(q);el.hidden=!match||!q&&!this.showAllCategories&&i>=6;if(!el.hidden)count++;});document.querySelector('#catalogCount').textContent=q?`${count} matching poster ${count===1?'type':'types'}`:this.showAllCategories?`${categories.length} poster types · ${categories.length*6} starting presets`:'Six starting points. More when you need them.';document.querySelector('#catalogMore').textContent=this.showAllCategories?'Show the six starting points':`Explore all ${categories.length} types ↗`;}
 applyZoom(){const viewport=document.querySelector('#canvasViewport');if(!viewport||viewport.clientWidth===0)return;const base=Math.min(440,Math.max(150,viewport.clientWidth-32));const width=Math.round(base*this.zoom/100);if(this.host.style.width!==width+'px'){this.host.style.width=width+'px';this.host.style.maxWidth='none';}this.paint();}
 selectedNodes(){return this.doc().nodes.filter(n=>this.selection.has(n.id));}
 rebuildGroup(n){
   const before=n.base,cx=n.x+n.width/2,cy=n.y+n.height/2,sx=n.width/before.width,sy=n.height/before.height,angle=n.rotation*Math.PI/180;
   n.source=n.groupChildren.map(child=>this.nodeSvg(child)).join('');const next=this.measure(n.source);
   const dx=(next.x+next.width/2-before.x-before.width/2)*sx*(n.flipX?-1:1),dy=(next.y+next.height/2-before.y-before.height/2)*sy*(n.flipY?-1:1);
   n.base=next;n.width=next.width*sx;n.height=next.height*sy;n.x=cx+dx*Math.cos(angle)-dy*Math.sin(angle)-n.width/2;n.y=cy+dx*Math.sin(angle)+dy*Math.cos(angle)-n.height/2;
 }
 updateBinding(key){super.updateBinding(key);const binding=key==='currency'?'price':key,value=binding==='price'?[state.currency,state.price].filter(Boolean).join(' '):state[binding],max={kicker:50,headline:19,subtitle:42,price:20,footer:76}[binding];const visit=nodes=>{for(const n of nodes){if(n.binding===binding)this.setText(n,value,max);if(n.groupChildren){visit(n.groupChildren);this.rebuildGroup(n);}}};for(const doc of Object.values(state.scenes||{}))for(const n of doc.nodes)if(n.groupChildren){visit(n.groupChildren);this.rebuildGroup(n);}}
 recolor(old){super.recolor(old);const next=this.colors();const visit=nodes=>{for(const n of nodes){this.rewrite(n,root=>root.querySelectorAll('*').forEach(el=>['fill','stroke'].forEach(attr=>{const i=old.indexOf(el.getAttribute(attr));if(i>=0)el.setAttribute(attr,next[i]);})),true);if(n.groupChildren){visit(n.groupChildren);this.rebuildGroup(n);}}};for(const doc of Object.values(state.scenes||{}))for(const n of doc.nodes)if(n.groupChildren){visit(n.groupChildren);this.rebuildGroup(n);}}
 input(e){super.input(e);if(e.target.id==='font'){const family=state.font==='sans'?'Arial, sans-serif':state.font==='mono'?'Courier New, monospace':'Georgia, serif';const visit=nodes=>{for(const n of nodes){if(n.type==='text')this.rewrite(n,root=>root.querySelector('text')?.setAttribute('font-family',family));if(n.groupChildren){visit(n.groupChildren);this.rebuildGroup(n);}}};for(const doc of Object.values(state.scenes||{}))for(const n of doc.nodes)if(n.groupChildren){visit(n.groupChildren);this.rebuildGroup(n);}this.changed();}}
 bounds(nodes=this.selectedNodes()){const boxes=nodes.map(n=>{const rad=n.rotation*Math.PI/180,w=Math.abs(n.width*Math.cos(rad))+Math.abs(n.height*Math.sin(rad)),h=Math.abs(n.width*Math.sin(rad))+Math.abs(n.height*Math.cos(rad));return{x:n.x+n.width/2-w/2,y:n.y+n.height/2-h/2,width:w,height:h};});const x=Math.min(...boxes.map(b=>b.x)),y=Math.min(...boxes.map(b=>b.y));return{x,y,width:Math.max(...boxes.map(b=>b.x+b.width))-x,height:Math.max(...boxes.map(b=>b.y+b.height))-y};}
 select(id,open=false,additive=false){if(!additive)this.selection.clear();if(id){if(additive&&this.selection.has(id))this.selection.delete(id);else this.selection.add(id);}this.selected=[...this.selection].at(-1)||null;this.render();if(open)this.openTab('object');}
 render(){if(!this.selection)this.selection=new Set();const valid=new Set(this.doc().nodes.map(n=>n.id));this.selection=new Set([...this.selection].filter(id=>valid.has(id)));if(this.selected&&valid.has(this.selected)&&!this.selection.has(this.selected)){this.selection.clear();this.selection.add(this.selected);}if(!this.selected)this.selection.clear();super.render();document.querySelector('#customPaper').hidden=state.paper!=='custom';const f=paperSize(state);document.querySelector('#sizeCaption').textContent=`${f.label} · ${f.w} × ${f.h} mm`;for(const key of ['customWidth','customHeight'])if(document.activeElement.id!==key)document.querySelector('#'+key).value=state[key]||(key==='customWidth'?210:297);}
 paint(){super.paint();const svg=this.host.querySelector('svg');if(!svg)return;if(this.grid){const g=document.createElementNS(svg.namespaceURI,'g');g.setAttribute('class','editor-grid');g.setAttribute('pointer-events','none');let lines='';for(let x=40;x<600;x+=40)lines+=`<path d="M${x} 0V${this.dimensions().height}"/>`;for(let y=40;y<this.dimensions().height;y+=40)lines+=`<path d="M0 ${y}H600"/>`;g.innerHTML=lines;g.setAttribute('stroke','#9469ba');g.setAttribute('stroke-opacity','.2');g.setAttribute('stroke-width','.7');svg.append(g);}if(this.guides){const g=document.createElementNS(svg.namespaceURI,'g');g.setAttribute('pointer-events','none');g.setAttribute('stroke','#d46fac');g.setAttribute('stroke-width','1');g.setAttribute('stroke-dasharray','5 4');g.innerHTML=(this.guides.x!==undefined?`<path d="M${this.guides.x} 0V${this.dimensions().height}"/>`:'')+(this.guides.y!==undefined?`<path d="M0 ${this.guides.y}H600"/>`:'');svg.append(g);}}
 selectionSvg(){if(!this.selection||this.selection.size<=1)return super.selectionSvg();const nodes=this.selectedNodes().filter(n=>!n.hidden);if(!nodes.length)return'';const b=this.bounds(nodes);return `<g pointer-events="none" fill="none" stroke="#a168bd" stroke-width="1.4" vector-effect="non-scaling-stroke"><rect x="${b.x}" y="${b.y}" width="${b.width}" height="${b.height}" stroke-dasharray="5 3"/>${nodes.map(n=>`<rect x="${n.x}" y="${n.y}" width="${n.width}" height="${n.height}" transform="rotate(${n.rotation} ${n.x+n.width/2} ${n.y+n.height/2})" opacity=".55"/>`).join('')}</g>`;}
 inspector(){
   if(this.selection?.size>1){const el=document.querySelector('#objectTab');el.innerHTML=`<div class="selection-empty"><b>${this.selection.size} layers selected</b><p>Drag any selected element to move them together. Group them to resize or rotate as one.</p></div><div class="object-actions"><button data-command="group">Group selection</button><button data-action="duplicate">Duplicate</button><button data-action="delete">Delete</button></div><label>Align selected layers</label><div class="align-grid">${['left','center','right','top','middle','bottom'].map(a=>`<button data-command="selection-align" data-align="${a}">${a}</button>`).join('')}</div><div class="object-actions"><button data-command="distribute" data-axis="x">Distribute ↔</button><button data-command="distribute" data-axis="y">Distribute ↕</button></div>`;return;}
   const n=this.node();if(n?.type==='group'){
     const el=document.querySelector('#objectTab');if(el.contains(document.activeElement)&&document.activeElement.matches('input'))return;
     el.innerHTML=`<div class="object-heading"><strong>${esc(n.name)}</strong><span>GROUP</span></div><p class="hint">${n.groupChildren?.length||0} layers move, resize, and rotate together.</p><div class="two-col">${['x','y','width','height','rotation'].map(k=>`<label>${k}<input data-prop="${k}" type="number" value="${Math.round(n[k])}"></label>`).join('')}</div><div class="object-actions"><button data-action="ungroup">Ungroup</button><button data-action="duplicate">Duplicate</button><button data-action="delete">Delete</button></div>`;return;
   }super.inspector();
 }
 layers(){super.layers();const rows=document.querySelectorAll('.layer-row');rows.forEach(row=>{row.classList.toggle('active',this.selection?.has(row.querySelector('[data-layer]')?.dataset.layer));});}
 checkpoint(coalesce=false,key=''){const now=Date.now(),group=`${this.selected}/${key}`;if(coalesce&&group===this.lastCheckpointKey&&now-this.lastCheckpoint<600)return;this.undoStack.push({state:JSON.stringify(StudioStorage.pack(state)),selected:this.selected,selection:[...this.selection||[]]});if(this.undoStack.length>30)this.undoStack.shift();this.redoStack=[];this.lastCheckpoint=now;this.lastCheckpointKey=coalesce?group:null;}
 history(redo=false){const from=redo?this.redoStack:this.undoStack,to=redo?this.undoStack:this.redoStack;if(!from.length)return;to.push({state:JSON.stringify(StudioStorage.pack(state)),selected:this.selected,selection:[...this.selection]});const entry=from.pop();state=StudioStorage.unpack(JSON.parse(entry.state));this.selected=entry.selected;this.selection=new Set(entry.selection||[entry.selected].filter(Boolean));this.lastCheckpoint=0;this.lastCheckpointKey=null;syncInputs();renderEditor();}
 pointerDown(e){const id=e.target.closest('[data-node]')?.dataset.node;if(e.shiftKey&&id){e.preventDefault();this.select(id,true,true);return;}if(this.selection.size>1&&id&&this.selection.has(id)){e.preventDefault();const nodes=this.selectedNodes();if(nodes.some(n=>n.locked))return;this.multiDrag={pointerId:e.pointerId,start:this.localPoint(e),nodes:nodes.map(n=>({id:n.id,x:n.x,y:n.y})),moved:false};this.host.setPointerCapture(e.pointerId);this.host.focus({preventScroll:true});return;}this.selection.clear();if(id)this.selection.add(id);super.pointerDown(e);}
 pointerMove(e){if(this.multiDrag){const d=this.multiDrag;if(e.pointerId!==d.pointerId)return;const p=this.localPoint(e),dx=p.x-d.start.x,dy=p.y-d.start.y;if(!d.moved&&Math.hypot(dx,dy)>.1){this.checkpoint();d.moved=true;}for(const before of d.nodes){const n=this.doc().nodes.find(n=>n.id===before.id);n.x=before.x+dx;n.y=before.y+dy;}this.paint();return;}super.pointerMove(e);if(this.drag?.handle==='move'&&this.snap&&!e.altKey){const n=this.node();if(!n)return;const xs=[0,300,600],ys=[0,this.dimensions().height/2,this.dimensions().height];for(const other of this.doc().nodes)if(other!==n&&!other.hidden&&other.role!=='background'){xs.push(other.x,other.x+other.width/2,other.x+other.width);ys.push(other.y,other.y+other.height/2,other.y+other.height);}const nearest=(values,edges)=>{let hit=null;for(const value of values)for(const edge of edges){const delta=value-edge;if(Math.abs(delta)<5&&(!hit||Math.abs(delta)<Math.abs(hit.delta)))hit={value,delta};}return hit;};const x=nearest(xs,[n.x,n.x+n.width/2,n.x+n.width]),y=nearest(ys,[n.y,n.y+n.height/2,n.y+n.height]);this.guides={};if(x){n.x+=x.delta;this.guides.x=x.value;}if(y){n.y+=y.delta;this.guides.y=y.value;}this.paint();}}
 pointerEnd(e,cancel=false){if(this.multiDrag){const d=this.multiDrag;this.multiDrag=null;if(cancel){for(const b of d.nodes){const n=this.doc().nodes.find(n=>n.id===b.id);Object.assign(n,{x:b.x,y:b.y});}if(d.moved)this.undoStack.pop();}if(this.host.hasPointerCapture(d.pointerId))this.host.releasePointerCapture(d.pointerId);this.changed();return;}this.guides=null;super.pointerEnd(e,cancel);}
 group(){const nodes=this.selectedNodes().filter(n=>!n.locked&&!n.hidden);if(nodes.length<2){toast('Shift-click at least two unlocked layers to group them.');return;}this.checkpoint();const flatten=(n,prefix='',opacity=1)=>{if(n.groupChildren)return n.groupChildren.flatMap(child=>flatten(child,(prefix+' '+this.transform(n)).trim(),opacity*n.opacity));if(!prefix)return[structuredClone(n)];return[this.makeNode(`<g transform="${prefix}">${this.nodeSvg(n)}</g>`,n.name,{type:n.type,binding:n.binding,opacity})];};const children=nodes.flatMap(n=>flatten(n));const source=children.map(n=>this.nodeSvg(n)).join('');const group=this.makeNode(source,'Group',{type:'group',groupChildren:children});const all=this.doc().nodes,index=Math.max(...nodes.map(n=>all.indexOf(n)));this.doc().nodes=all.filter(n=>!nodes.includes(n));this.doc().nodes.splice(Math.min(index,this.doc().nodes.length),0,group);this.selection=new Set([group.id]);this.selected=group.id;this.changed();}
 ungroup(n){if(!n.groupChildren)return super.ungroup(n);const children=n.groupChildren.map(child=>{const source=`<g transform="${this.transform(n)}">${this.nodeSvg(child)}</g>`;return this.makeNode(source,child.name,{type:child.type,binding:child.binding,opacity:n.opacity,groupChildren:child.groupChildren});});const nodes=this.doc().nodes,index=nodes.indexOf(n);nodes.splice(index,1,...children);this.selection=new Set(children.map(n=>n.id));this.selected=children.at(-1)?.id||null;}
 action(action){if(this.selection.size>1&&['delete','duplicate'].includes(action)){this.checkpoint();const nodes=this.selectedNodes().filter(n=>!n.locked);if(action==='delete'){this.doc().nodes=this.doc().nodes.filter(n=>!nodes.includes(n));this.selection.clear();this.selected=null;}else{const copies=nodes.map(n=>({...structuredClone(n),id:this.id(),name:n.name+' copy',x:n.x+18,y:n.y+18,binding:null,role:null}));this.doc().nodes.push(...copies);this.selection=new Set(copies.map(n=>n.id));this.selected=copies.at(-1)?.id;}this.changed();return;}super.action(action);}
 alignSelection(side){const nodes=this.selectedNodes().filter(n=>!n.locked);if(nodes.length<2)return;this.checkpoint();const b=this.bounds(nodes);for(const n of nodes){if(side==='left')n.x=b.x;if(side==='center')n.x=b.x+(b.width-n.width)/2;if(side==='right')n.x=b.x+b.width-n.width;if(side==='top')n.y=b.y;if(side==='middle')n.y=b.y+(b.height-n.height)/2;if(side==='bottom')n.y=b.y+b.height-n.height;}this.changed();}
 distribute(axis){const nodes=this.selectedNodes().filter(n=>!n.locked).sort((a,b)=>a[axis]-b[axis]);if(nodes.length<3){toast('Select at least three layers to distribute them.');return;}this.checkpoint();const size=axis==='x'?'width':'height',first=nodes[0][axis],end=nodes.at(-1)[axis]+nodes.at(-1)[size],total=nodes.reduce((sum,n)=>sum+n[size],0),gap=(end-first-total)/(nodes.length-1);let pos=first;nodes.forEach(n=>{n[axis]=pos;pos+=n[size]+gap;});this.changed();}
 selectAll(){this.selection=new Set(this.doc().nodes.filter(n=>!n.locked&&!n.hidden).map(n=>n.id));this.selected=[...this.selection].at(-1)||null;this.render();this.openTab('object');}
 renderLibrary(){if(!document.querySelector('#artCollection'))return;const q=document.querySelector('#artSearch').value.toLowerCase().trim();const terms=q.split(/\s+/).filter(Boolean);const patterns={food:/food|bakery|bread|drink|restaurant|coffee|cake|fruit/,animals:/animal|pet|cat|dog|nature|plant|flower|bird|fish/,work:/work|school|education|business|hiring|career|learning|art |tools/,outdoor:/travel|sport|outdoor|camp|fitness|weather|adventure/,graphic:/geometric|graphic|pattern|abstract|shape|starburst|rosette|sticker|mesh/};const items=Object.entries(artwork).filter(([id,a])=>terms.every(t=>(id+' '+a[0]).includes(t))&&(this.collection==='all'||this.collection==='favorites'?this.collection!=='favorites'||this.favorites.has(id):patterns[this.collection]?.test(a[0])));const key=JSON.stringify([q,this.collection,this.artLimit,[...this.favorites]]);if(key===this.libraryKey)return;this.libraryKey=key;document.querySelector('#artCount').textContent=`${items.length} graphics`;document.querySelector('#artGrid').innerHTML=items.slice(0,this.artLimit).map(([id,a])=>`<div class="library-tile"><button class="art-item" data-art="${id}" title="${id}" aria-label="Add ${id}">${artSvg(id)}</button><button class="art-favorite ${this.favorites.has(id)?'active':''}" data-favorite="${id}" aria-label="${this.favorites.has(id)?'Unfavorite':'Favorite'} ${id}" aria-pressed="${this.favorites.has(id)}">${this.favorites.has(id)?'★':'☆'}</button></div>`).join('')||'<p class="hint">No graphics match. Try a shorter keyword or another collection.</p>';document.querySelector('#moreArt').hidden=items.length<=this.artLimit;}
 newBlank(){initializeDesign(0);state.scenes={};state.blank=true;for(const key of ['headline','kicker','subtitle','footer','price','currency'])state[key]='';this.selection.clear();this.selected=null;this.clearHistory();syncInputs();renderEditor();}
 click(e){const b=e.target.closest('button');if(!b)return;const stop=()=>{e.preventDefault();e.stopImmediatePropagation();};if(b.dataset.layer&&e.shiftKey){stop();this.select(b.dataset.layer,false,true);return;}if(b.dataset.favorite){stop();const id=b.dataset.favorite;if(this.favorites.has(id))this.favorites.delete(id);else this.favorites.add(id);try{localStorage.setItem('paperplane-favorite-art',JSON.stringify([...this.favorites]));}catch{}this.renderLibrary();return;}if(b.dataset.look!==undefined){this.selection.clear();state.blank=false;}if(b.id==='download'){stop();this.exportImage();return;}if(b.dataset.command){stop();this.command(b.dataset.command,b);return;}super.click(e);}
 command(cmd,b){if(cmd==='catalog-more'){this.showAllCategories=!this.showAllCategories;this.filterCategories();}else if(cmd==='blank')this.newBlank();else if(cmd==='more-art'){this.artLimit+=48;this.renderLibrary();}else if(cmd==='select-all')this.selectAll();else if(cmd==='group')this.group();else if(cmd==='selection-align')this.alignSelection(b.dataset.align);else if(cmd==='distribute')this.distribute(b.dataset.axis);else if(cmd==='help')document.querySelector('#shortcutsDialog').showModal();else if(cmd==='close-help')document.querySelector('#shortcutsDialog').close();else if(cmd==='projects')this.projects();else if(cmd==='close-dialog')document.querySelector('#projectDialog').close();else if(cmd==='save-project')this.saveProject();else if(cmd==='save-copy'){this.activeProject=null;document.querySelector('#projectName').value=(document.querySelector('#projectName').value||'Poster')+' copy';this.saveProject();}else if(cmd==='export-project')this.exportProject();else if(cmd==='current-draft'){document.querySelector('#projectDialog').close();if(state.headline||state.blank){syncInputs();renderEditor();showStep(3);}else toast('Create a poster to start your draft.');}else if(cmd==='load-project')this.loadProject(b.dataset.id);else if(cmd==='delete-project')this.deleteProject(b.dataset.id);else if(cmd==='print')this.print();}
 keydown(e){if(state.step===3&&!e.target.closest('input,textarea,select,[contenteditable=true]')&&!document.querySelector('dialog[open]')){const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(mod&&key==='a'){e.preventDefault();this.selectAll();return;}if(mod&&key==='g'){e.preventDefault();if(e.shiftKey)this.action('ungroup');else this.group();return;}if(this.selection.size>1&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();this.checkpoint(true,'multi-move');const d=e.shiftKey?10:1;for(const n of this.selectedNodes().filter(n=>!n.locked)){if(e.key==='ArrowLeft')n.x-=d;if(e.key==='ArrowRight')n.x+=d;if(e.key==='ArrowUp')n.y-=d;if(e.key==='ArrowDown')n.y+=d;}this.changed();return;}}if(document.querySelector('dialog[open]'))return;super.keydown(e);}
 async projects(){const dialog=document.querySelector('#projectDialog');if(!dialog.open)dialog.showModal();document.querySelector('#projectName').value=this.projectName||state.headline?.replace(/\n/g,' ')||'';await this.projectList();}
 async projectList(){try{this.records=(await StudioStorage.list()).sort((a,b)=>b.updated-a.updated);document.querySelector('#projectList').innerHTML=this.records.map(r=>`<div class="project-row"><button data-command="load-project" data-id="${r.id}"><strong>${esc(r.name)}</strong><small>${new Date(r.updated).toLocaleString()} · ${categories.find(c=>c.id===r.category)?.name||'Poster'}</small></button><button data-command="delete-project" data-id="${r.id}" aria-label="Delete ${esc(r.name)}">×</button></div>`).join('')||'<p class="hint">No named projects yet. Save your current design above.</p>';document.querySelector('#projectMessage').textContent='Named projects stay in this browser. Download a project file to keep a portable copy.';}catch(error){document.querySelector('#projectMessage').textContent=error.message+' You can still download a project file.';}}
 async saveProject(){if(!state.headline&&!state.blank){toast('Create a poster before saving a project.');return;}const name=document.querySelector('#projectName').value.trim()||'Untitled poster';try{const id=this.activeProject||this.id();await StudioStorage.put({id,name,updated:Date.now(),category:state.category,data:StudioStorage.pack(state)});this.activeProject=id;this.projectName=name;await this.projectList();toast('Project saved on this device.');}catch{toast('Project could not be saved here. Download a project file instead.');}}
 async loadProject(id){try{const r=this.records.find(r=>r.id===id);const loaded=StudioStorage.validate(StudioStorage.unpack(r.data));state=loaded;this.activeProject=id;this.projectName=r.name;this.selected=null;this.selection.clear();this.clearHistory();syncInputs();renderEditor();showStep(3);document.querySelector('#projectDialog').close();toast('Project opened.');}catch(error){toast(error.message);}}
 async deleteProject(id){try{await StudioStorage.remove(id);if(this.activeProject===id){this.activeProject=null;this.projectName=null;}await this.projectList();toast('Saved project deleted. The current canvas is still available.');}catch{toast('Could not delete this project.');}}
 exportProject(){if(!state.headline&&!state.blank){toast('Create a poster first.');return;}const name=(document.querySelector('#projectName').value||this.projectName||'poster').replace(/[^a-z0-9_-]+/gi,'-').slice(0,60);downloadBlob(new Blob([JSON.stringify(StudioStorage.pack(state))],{type:'application/json'}),name+'.paperplane.json');toast('Editable project downloaded.');}
 async importProject(e){const file=e.target.files[0];if(!file)return;try{if(file.size>25000000)throw Error('Project files must be smaller than 25 MB.');const loaded=StudioStorage.validate(StudioStorage.unpack(JSON.parse(await file.text())));state=loaded;this.activeProject=null;this.projectName=file.name.replace(/\.paperplane\.json$|\.json$/g,'');this.selected=null;this.selection.clear();this.clearHistory();syncInputs();renderEditor();showStep(3);document.querySelector('#projectDialog').close();toast('Project imported. Save it here to keep a named copy.');}catch(error){toast(error.message||'Could not open that project.');}e.target.value='';}
 async importSvg(e){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('SVG files must be smaller than 2 MB.');const parsed=new DOMParser().parseFromString(await file.text(),'image/svg+xml');if(parsed.querySelector('parsererror')||parsed.documentElement.localName!=='svg')throw Error('Choose a valid SVG file.');const svg=parsed.documentElement;const vb=(svg.getAttribute('viewBox')||'').split(/[ ,]+/).map(Number);const w=Number.parseFloat(svg.getAttribute('width'))||vb[2]||100,h=Number.parseFloat(svg.getAttribute('height'))||vb[3]||100;if(![w,h].every(v=>Number.isFinite(v)&&v>0))throw Error('Invalid SVG dimensions.');if(!svg.hasAttribute('viewBox'))svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.setAttribute('width','240');svg.setAttribute('height',String(Math.min(600,240*h/w)));svg.setAttribute('x','180');svg.setAttribute('y','200');const source=new XMLSerializer().serializeToString(svg);const candidate={id:'svg-import-check',name:'Imported SVG',type:'shape',source,base:{x:0,y:0,width:100,height:100},x:0,y:0,width:100,height:100,rotation:0,opacity:1};StudioStorage.validate({...state,scenes:{0:{height:849,nodes:[candidate]}}});this.checkpoint();const node=this.makeNode(source,file.name.slice(0,100));this.doc().nodes.push(node);this.selected=node.id;this.selection=new Set([node.id]);this.changed();toast('SVG imported as an editable layer. Ungroup it to edit individual parts.');}catch(error){toast(error.message||'This SVG could not be opened.');}e.target.value='';}
 async exportImage(){const type=document.querySelector('#exportType').value,svg=this.svg();const name=(state.headline||'poster').toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,55)||'poster';if(type==='svg'){downloadBlob(new Blob([svg],{type:'image/svg+xml'}),name+'.svg');return;}const button=document.querySelector('#download');button.disabled=true;button.textContent='Exporting…';const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});const f=paperSize(state),dpi=Number(document.querySelector('#exportQuality').value),scale=Math.min(1,10000/Math.max(f.w/25.4*dpi,f.h/25.4*dpi));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(f.w/25.4*dpi*scale));canvas.height=Math.max(1,Math.round(f.h/25.4*dpi*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,type==='jpeg'?'image/jpeg':'image/png',.94));if(!blob)throw Error();downloadBlob(blob,name+(type==='jpeg'?'.jpg':'.png'));toast(`Downloaded ${canvas.width} × ${canvas.height} image${scale<1?' (limited to 10,000 px)':''}.`);}catch{toast('Image export could not finish. Try SVG instead.');}finally{URL.revokeObjectURL(url);button.disabled=false;button.textContent='Download ↗';}}
 print(){const previous=document.querySelector('#printSheet');previous?.remove();const sheet=document.createElement('div');sheet.id='printSheet';sheet.innerHTML=this.svg();document.body.append(sheet);const f=paperSize(state);let style=document.querySelector('#printPageStyle');if(!style){style=document.createElement('style');style.id='printPageStyle';document.head.append(style);}style.textContent=`@page{size:${f.w}mm ${f.h}mm;margin:0}@media print{#printSheet{width:${f.w}mm;height:${f.h}mm}}`;window.print();}
}
